WITH filtered AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, shipping_fee, CASE WHEN discount >= 0.38 THEN 'High' WHEN discount >= 0.15 THEN 'Medium' ELSE 'Low' END AS discount_level, COALESCE(channel, 'DIRECT') AS channel_clean FROM orders WHERE order_date >= DATE '2023-12-18' AND store_id IS NOT NULL), matched AS (SELECT src.*, sub.id AS subscription_id, sub.plan, sub.monthly_fee FROM filtered src LEFT JOIN subscriptions sub ON src.customer_id = sub.customer_id AND src.order_date BETWEEN sub.start_date AND sub.end_date), deduped AS (SELECT * FROM matched QUALIFY RANK() OVER (PARTITION BY store_id ORDER BY order_date) = 1), metrics AS (SELECT *, AVG(amount) OVER (PARTITION BY customer_id ORDER BY monthly_fee, id, subscription_id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS amount_avg_5_prior, AVG(shipping_fee) OVER (PARTITION BY status ORDER BY shipping_fee, id, subscription_id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS shipping_fee_avg_5_prior, ROW_NUMBER() OVER (PARTITION BY store_id, channel ORDER BY amount DESC, id, subscription_id) AS event_seq FROM deduped), metrics_orders AS (SELECT *, SUM(amount) OVER (PARTITION BY customer_id ORDER BY monthly_fee, id, subscription_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount, RANK() OVER w_ordered AS amount_rank FROM metrics WINDOW w_ordered AS (PARTITION BY customer_id ORDER BY amount NULLS LAST)) SELECT s.id, s.store_id, s.order_date, s.channel, s.amount, s.shipping_fee, s.discount_level, s.channel_clean, s.subscription_id, (SELECT SUM(x.discount) FROM orders x WHERE x.store_id = s.store_id) AS sum_order_discount FROM metrics_orders s ORDER BY shipping_fee DESC
